from build_research import *
CARDS=[];CHAR={};SCENES={}
def card(typ,key,title,content,ids,kind='synthesis'):
 c={'asset_type':typ,'scope':'reusable-pattern' if typ=='pattern' else 'source-analysis','title':title,'origin_key':PREFIX+typ+'/'+key,'tags':['作者:失落叶','作品:网游之纵横天下','卷七',{'character':'人物阶段','scene':'场景机制','pattern':'可迁移机制'}[typ]],'content':content,'evidence':ev(ids,kind),'user_notes':'','favorite':False,'review_status':'draft'}
 CARDS.append(c);return c
def character(key,title,summary,goal,constraints,relations,decisions,change,ids):
 c=card('character',key,title,dict(summary=summary,goals=[goal],constraints=[constraints],relationship_directions=[relations],decisions=[decisions],stage_change=change,knowledge_boundary='仅记录卷七已发生；系统/本人自述/旁人转述/主角猜测区分；尾段由primary实读。'),ids)
 CHAR[key]=c;return c
character('shusheng','轻狂书生（丁书生）','清风保卫战中圣域归零，随后重建战力、企业与军团，卷末270但北冥不能用。','护同伴、保持自主、成长并让组织有收入。','灵力/装备资格/技能格/补给/信息范围；关系承诺不一致。','雪深爱但她未明确知秦床事；秦由出走至亲密；月主动爱仍出国；冰茶暧昧未定；七星合作与抢夺反复。','承认甩手管理失误、拒父资助创业；既救公共防线又垄断军需和强取装备；达尔后强夺回天钥。','卷末270，五永恒/苍穹盾实穿，小青可骑，三郡一王守护有容量极限；自辩与愧疚仍并存。',[779,786,867,869,949,996,1039,1041,1055,1059])
