character('linqiu','林丘','护主将领同时怀兄仇，最终失心后被斩首真死。','护菲雅、为兄林克复仇。','独臂/力量差、达尔再生与绝对攻击。','林克是兄非同人；妻米拉披风为本刻情感物；茉莉共同迎敌。','血刃战重伤，天钥战持兵迎达尔，危急救菲雅遭掏心，下一章被斩首。','1035明确最终死亡，未获复活；不能用剧情弥留阶段偷写可救成功。',[899,1031,1032,1034,1035])
character('wangzuo','野蛮王座','跨国强敌具操作、调度和自知，随新装备成长，末仍活。','拓领保猛虎盟、争胜。','禁骑环境/同伴损失/敌多方协作；非血脉自动亲中。','部下吹捧被其反斥；与擎天可共同抗雪，风旋破单挑令局部荣誉失效。','安定诱敌转曙光、几次攻城/北迁；遗迹1v3被书偷袭杀；通缉时卡剑并逼双人。','1053新地龙血套/烈阳剑已见，1054未死而被多人打断；不把主角内心排名作为永恒客观榜。',[947,950,951,971,973,976,980,1053,1054])
character('xunfang','荀方','现实旧同学告白受拒，转游戏挑战并已受亲属资源扶持。','追雪、争中国第一。','雪明确拒绝、本人尚新号、能力等级未定。','孤坟远侄亲口确认，地狱火等带练已实；书猜压雪政治目的未证。','饭局相识后想单聊、拒绝后向服务生摔杯迁怒且结账；称将暂放商业入游。','末受带练但255只是孤预计；没有已成强敌/取代书，也无雪同意赌身。',[1057,1058,1059])
character('ziyue','紫月','有限操作的刺客，有实用建议与跨阵营友情，非群体附属。','共同生活、自由交友、进步。','装备与操作差距，非所有场景能主战。','乐兮半月伙伴主动介绍；与夏雨相亲近但不是同一人物。','建议副本避追；拒带练有自己的朋友；介绍乐兮、持续探访；醉夜唯一清醒驾车。','已过220圣域有本卷确认；不能由早期笑料固定为无用，也不拔高为第一刺客。',[784,949,962,975,977,987,1023,1030])
character('xiatian','去年夏天（夏天）','召唤师功能有限却多次有尾杀、屏障和防区贡献。','参与成长与工作室生活。','宠物后期受圣域压制；常遭身体调笑。','与紫月/落雨独立；贪狼收益不可并给主角。','清风尾暗骑获盾并接受雪出价、阵地宠障、千秋战贪狼尾残月、十波守龙与地齿合冲。','战功属可限定协作，非万能；莫雷盾同意卖10万与实际到账文本未拍要分。',[798,896,912,949,1009,1055])
character('luoyu','落雨无声','职业弓手与同伴，主战后排保护及指挥具有可见分工。','稳定输出、参与团队并成长。','等级/资源倾斜、后期强敌压力。','与夏紫共同生活而角色实体独立；装备皮胸给谁有源文疑点。','带十弓持续保护三法牧；与暗影等伏王座；天钥外围指挥弓晕法牧阵。','其稳定辅助不等所有场合无代价；989零度皮胸先拟她后交月称给紫须留歧义。',[798,949,970,989,1030])
character('lingtian','凌天','由严控分离至犯罪风险后保护并明确放下左右，资源权力仍在。','护两女、安排事业/继承。','掌握大资本但不能消除暴力风险与关系自主。','书拒资助仍创业；月跪血无效；后叫书返苏并不必再回南京。','要求三年/两选、后以安全召回，安排保护/海外实习/有条件股权继承。','982已明确累了不再左右；秦0.7%实得，89%未来分三份要订婚生效仍承诺，未可填书现拥有。',[868,869,981,982,1013,1020,1042])

def scene(key,title,summary,goal,obstacle,choice,consequence,state,why,app,fail,ids,chars):
 c=card('scene',key,title,dict(summary=summary,goal=goal,obstacle=obstacle,choice=choice,consequence=consequence,state_change=state,why_it_works=why,applicability=app,failure_mode=fail,characters=[CHAR[k]['origin_key'] for k in chars]),ids)
 SCENES[key]=c;return c

scene('relevel','归零后的弓靴与留怪','败城中先得圣域体验再归零，接受同伴资源才恢复战力。','升50用赤霄。','防5裸身、技能资源/高怪无经验、装备门槛。','雪找低弓/赠靴、公开征怪花10万、众人压血书尾。','实际50且赤霄装，仍需2400万技能/后续装备。','从全装短时强转低装脆弱再形成协作闭环。','失败暴露具体缺口，物件以真实用途回收。','重建成长先列失去和补齐路径。','直接获高成长即写无敌会抹代价；别把留怪尾杀写独杀。',[778,779,781,785,786,787],['shusheng','lingxue','lingyue'])
scene('lifeduel','生死决与毁耐久','可见双方坐标把争怪升级为强制对决。','杀七星并交任务。','七星墓地回血/无敌、群援，书也会中诅咒。','先耗敌无敌，重追击毁其剑耐久；杀后请悲援撤。','目标死并爆绑定护腿，交才59；千人清由团队。','任务已成/群战另算。','规则限制和失手保留真实不确定。','用具体新工具回收，拆目标杀与后续撤离。','胜之不武自称不能盖后续主动求援。',[788,789,790,791],['shusheng','qixing','linger'])
scene('qingfeng','清风回收的传送后勤链','野战包围不全灭，暗杀四传送管理员再造攻城条件。','正式收复清风。','敌城防/远程/援军、24h断传时限。','宠物吸控暗杀、令牌亡灵耗防、工匠云梯、多人合技/弓保护法牧。','书16逸1杀17龙骑，雪斩公爵后系统回收；书105盾150未能装。','城由正式结算确认，个人战功与资格分离。','每道障碍都有职业工具而非一句围攻。','空间战先画物流与防守条件。','删工匠/牧弓只留主角伤害会破因果。',[792,793,794,795,796,797,798,799],['shusheng','lingxue','lingyue','yix','bingcha','mofang','luoyu','xiatian','qixing'])
scene('sagelong','柱距与毒的萨格隆','近战首败后退到空间安全边界、末段叫队回来。','击败高阶神级。','首轮正面扛不住。','利用柱/距离与毒持续，再把末段经验分给队。','击杀与交付分时，书159后162；159才实穿150盾。','强度通过方法而非硬数值绕。','失败诊断到换法有可追踪动作。','为越级战保空间/时间/补给成本。','单写毒必胜不保目标回复/射程会泛化失真。',[810,815,816,817],['shusheng','qinyun','linger'])
scene('s3','玄武与死后毒续','多次灭团后秦观察死亡不清毒，团队用规则续伤。','完成S3。','高王多次团灭，常规硬扛不成。','秦观察，重复控制、死亡和毒持续，最后合技收。','首通与后刷全套分开。','观察者非主角独占。','可见异常改方案并保失败成本。','让辅助职业发现独特解法。','把复活写无限免费会失挑战。',[823,824,825,826],['shusheng','lingxue','qinyun','lingyue','bingcha'])
scene('gale','疾风城火攻与撤军','佯攻、亡灵引军和枯木火攻造成巨大战果及不可抹损失。','攻疾风并保突入队。','多军团与炮、盟友百万被困。','五炮永久牺牲属性，枯木火攻；秦质疑杀戮，书仍执行；战后独救配全会撤。','疾风黑暗占领正式公告、孤军安全撤；雪秦及多同伴死书掉级。','目标完成不消伦理和战损。','谋略具体触发与不同人物成本并列。','战略场景安排提出者/执行者/承损者。','以胜利倒推每次牺牲最优或正义不成立。',[835,836,837,838,839,845,846,847],['shusheng','lingxue','qinyun','gufen'])
scene('s4','S4首通：治疗判断与蛇王控','多层失败分别改分工，秦指耐烧和独潜一剑。','完成S4并给冰凑装。','熊蛇魔域强度/全图火、命中MISS。','双圣远攻、雪卡仇、秦插疗/建议火后策略；末隐身一剑由规则窗口支持。','首通但青魂未一日全套，经验864才领。','控制、耐受和时间分工重组。','不把几个王写同一无脑复用招。','每一阶段失败后改变一个关键条件。','忘治疗/死次或预支尚未领奖会净化过程。',[856,857,858,859,860,861,862,863,864],['shusheng','lingxue','qinyun','bingcha','aini'])
scene('split','剑火出离与组织重建','旧恩召回旧部，书当面允离却付大组织损失。','保存雪月与同伴情义。','林霜旧权威、龙魂自述旧回忆、刑天母嘱；书推龙魂暗恋；秦失望和声誉流言。','不强扣成员；承认管理甩手，任新管/合梦回重组。','主盟不足8000后重整十万，整体未全恢复；秦房空删友。','组织与私人伤害不同步解决。','不同归属诉求没有一场战斗可解决。','组织崩解用人员/权限/资源具体落点。','道德宽容不能自动取消管理责任。',[866,867,868],['shusheng','linshuang','longhun','qinyun','suifeng','mofang'])
scene('business','南京创业与有限的自主','拒资助离苏，书把手艺与用人转经营。','在三年考验/分离中立足。','父资本权、餐饮现金/人事/供应。','拒卡选南京，买鱼塘/酒楼、聘厨经理，处理员工受辱。','甘泉梦乡实际开但未即回本；50000买衣未付/补员工1000分别记。','经营成形而感情分离仍在。','自主通过具体支出和责任形成，不只口号。','现实事业线需报支付/估值/利润各状态。','用开业等稳赚、用主角猜幕后审批当证实。',[868,869,871,872,914,944],['shusheng','lingtian','lingyue','xiang'])
scene('destroy','诸神之怒：守不住再建设','多波互保和临机引怪仍城毁，雨露新村随后实际建。','守王都后保工民重建。','怪群远程/飞行/破墙、总兵力差。','团队尝试分波控和NPC后卫；城毁后搬迁村、广告补给和日常。','书掉级、新村人口/军力字段实示，等级建筑需再做。','毁城失败与新制度机遇相连。','城池可失才让重建经营有重量。','灾难场景保不可逆/可恢复两账。','把撤令未抵写全已安全或广告等自动满一切。',[872,873,874,875,876,877],['shusheng','lingxue','lingyue','qinyun','xiang','mofang'])
scene('mine','无牧金窟与后线袭村','无牧打矿救人，完成击王不等头颅已交。','救矿工、取矿并回保驻地。','无常规牧、地图怪与敌百万来袭。','小组盾控/吸血、冰零度全团保护；组织外线回村。','静刃死奖励分，矿头交付尚未见；村战借香草夹后驱退。','支线收益与主线防务有时间竞争。','不可把任务道具到手直接视完成。','让缺职业形成不同解决法。','零度无敌时限不等全战无伤。',[879,880,881,882,883,884],['shusheng','lingxue','bingcha','xiang','suifeng'])
scene('bloodblade','白云再取与血刃尾杀','多波从攻城变守墙，顶战枯竭后雪完成首领奖励。','回收白云并击血刃。','墙毁/援敌/长时耗灵、会间抢尾。','工匠投石/龙骑NPC/轮控，预留合技与退让；雪无敌剑盾尾杀。','血刃死但多数熟人亡；书个人名次与广播矛盾保留，雪仍未凭此立飞。','多人协作与抢尾规则冲突。','敌首领战把前波消耗带入最终选择。','大型高潮拆主战/尾杀/正式城市结算。','把尾杀者或系统第一自动等全部首功。',[891,893,896,898,899,900,901,902],['shusheng','lingxue','lingyue','qinyun','xiang','bingcha','mofang','lesi','feiya','linqiu'])
scene('industry','银曜与毁灭剑的军团生产','私人坐骑发现扩成集中装备军团。','建立规模精骑、保刷珠矿。','掉落速度/材料/望消耗、敌围。','随风发现蛋、多人成批刷；首冲魂、救援补后勤；铁匠图一次永久。','3400珠/224首造177极品，后总万骑再五万/400甲分时；并非全员同一装备。','材料采集到制造到兵力反馈。','生产工具比单件神装能解释组织强。','原创改资源链与分配，不复制蛋/图名。','垄断刷新点与自由练级宣称矛盾不能抹。',[904,905,906,907,908,909,915,996,1029],['shusheng','lingxue','lingyue','suifeng','huahuo','yix'])
scene('minewar','紫矿冲突到千秋平原战','书先偷袭合杀残月，后组织军战换为干部执行。','保矿/检验军团。','敌控/箭压/乐兮合技，保护主帅。','先点杀乐兮破合技、后排抛射/指挥避王；书月山观但仍下令。','夏贪狼尾残，千秋文本称全歼、己低于20%；不把观战写不参与。','干部主战及弱职业具体作用。','调度和连招的功能落点明确。','组织成长用主角不必亲手所有尾杀来展示。','独立观战不等放任，全部公正国战评价不当事实。',[910,911,912,913],['shusheng','lingxue','lingyue','suifeng','mofang','lesi','xiatian'])
scene('aryan','暗黑镜囚与灵儿第三封','救援团也被囚，灵儿主动选择保护触发新阶段。','找亚兰并活着交盾。','神王暗镜、技能/传送禁、1血囚。','电话寻梦召队，诸强失败后灵儿反抗；封破后多人四合技控制收尾。','亚兰终死书232到236、永恒披风得后924实穿/交任务237。','救人者也受难，宠物行动关键。','先阻全部常规解再让成长由已有人物选择触发。','重要觉醒必须有代价与后续功能。','第三道即最后封：922解除宣布，963醒后展示归零裸装；不能提前醒后表现或当另解第四封。末击不等独杀。',[915,916,919,920,921,922,923,924],['shusheng','lingxue','lingyue','qinyun','bingcha','xiang','linger','aini','yix','huahuo'])
scene('qinreturn','秦韵的拒返、退租与归队','一次找到不够，承认情感损害后才分步回到南京和雪月。','修复关系并使秦愿返。','离别、自尊、误以共住战魂；多方关系不稳。','书野外救她仍被拒，现实姨设局；秦愿退租赔6000自己选择南京，随后入会。','现实返936/游戏937，雪远程接受竞争但性关系尚未发生。','情感/地点/会籍分别更新。','不把主角愿望当对方决定，对方几次说不有效。','关系修复给对方实际选择和退出成本。','姨称癌随后否认咽炎，不能记真癌治愈；三准女友非统一共识。',[918,932,933,934,935,936,937],['shusheng','qinyun','lingxue','lingyue','xiang','linshuang'])
scene('points','据点竞令、三线调会与补偿','日更万人复制战驱动转会兵力与盟友利益重排。','保暗金并夺回黄金。','魂主力转分破香草、主盟分兵后差距缩小。','尾秒投1247获资格，后六千多银曜临时转香草/梦回侧攻，书秦香留。','三线实胜主144:137险胜；盟友秋雨并盟要黄金，200万交凌月而逐人分未见。','胜利变持续守点/军备生产与联盟分配。','小规则使旧人脉/装备资产有新用途。','写资源/时间窗/反制/代价四环。','不要把自动战写现场操作、把下一日永久守住写既成。',[937,938,939,940,941,943,944],['shusheng','lingxue','lingyue','qinyun','xiang','qixing','bingcha','suifeng','gufen'])
